//! # The generated document: assembling it and reading its marker skeleton
//!
//! `code/specs/<impl>.warrant` is **generated** (VOS02 R2): the contract package's
//! contract block, then the implementation's hand-written block, then the obligations
//! blocks the implementation carries, each between marker comments, with the SHA-256 of
//! the copied blocks in the begin markers.
//!
//! ```text
//!   warrant vos_ready_bitmap v1
//!     -- vos02:generated by vos-link gen-doc; do not edit; contract-package=vos_ready_contract
//!     -- vos02:contract-begin sha256=<64 hex>
//!   ...the contract block, byte for byte...
//!     -- vos02:contract-end
//!     -- vos02:impl-begin
//!   ...the implementation block...
//!     -- vos02:impl-end
//!     -- vos02:obligations-begin tier=safety sha256=<64 hex>
//!   ...that tier's obligations, byte for byte...
//!     -- vos02:obligations-end
//!     assume platform:
//!       none
//!     assume environment:
//!       none
//! ```
//!
//! [`assemble`] writes it; [`parse_layout`] reads it back.  The reader is the
//! `vos_document` grammar pair (an exact line token for each of the seven markers, a
//! catch-all token for any other line that mentions `-- vos02:`, and a parser grammar
//! that fixes their order), so a marker that is forged, repeated, missing, moved or
//! unknown is a parse error and not a case somebody forgot.  A hand-written scanner
//! would be the thing the repository forbids.
//!
//! What the grammar cannot say, [`parse_layout`] checks after the parse: that the
//! tiers are sorted and unique.  What a *digest* says is not decided here; the layout
//! carries both the digest a marker records and the digest of the bytes ([`Block`]) and
//! `vos-link` compares them.

use lexer::grammar_lexer::GrammarLexer;
use parser::grammar_parser::{ASTNodeOrToken, GrammarASTNode, GrammarParser};

use crate::caps::{DOCUMENT_MAX_BYTES, DOCUMENT_MAX_LINE};
use crate::contract::{is_ident, Tier};
use crate::digest::sha256_hex;
use crate::grammar::{document_grammar, document_tokens, token_kind};
use crate::part::{admit_bytes, Part, PartErrorKind};

/// What went wrong with a document.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DocErrorKind {
    /// Over the byte cap (the assembled document, or the one read).
    TooLarge,
    /// A line over the line cap.
    LineTooLong,
    /// A control byte or a byte outside ASCII.
    Bytes,
    /// A package name that is not an `IDENT`.
    BadName,
    /// Obligations tiers not sorted and unique.
    TierOrder,
    /// The marker skeleton is wrong (order, count, forged or unknown marker).
    Structure,
}

/// A document error.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DocError {
    /// What went wrong.
    pub kind: DocErrorKind,
    /// 1-based line (1 when none is meaningful).
    pub line: u32,
    /// Human-readable reason.
    pub message: String,
}

impl DocError {
    /// True for a size cap: no verdict, not a failed rule.
    pub fn is_cap(&self) -> bool {
        matches!(
            self.kind,
            DocErrorKind::TooLarge | DocErrorKind::LineTooLong
        )
    }
}

impl std::fmt::Display for DocError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "line {}: {}", self.line, self.message)
    }
}

impl std::error::Error for DocError {}

fn err<T>(kind: DocErrorKind, line: usize, message: impl Into<String>) -> Result<T, DocError> {
    Err(DocError {
        kind,
        line: u32::try_from(line).unwrap_or(u32::MAX),
        message: message.into(),
    })
}

/// The lines of the generated trailer (VOS02 section 10.1, D-GD4): an implementation
/// assumes nothing (R7).
pub const TRAILER: &str = "  assume platform:\n    none\n  assume environment:\n    none\n";

/// The package name as it appears inside a document: `IDENT` with `-` as `_`
/// (`[a-z][a-z0-9_]{0,31}`, a Warrant name and a marker attribute).
pub fn document_name(ident: &str) -> Result<String, DocError> {
    if !is_ident(ident) {
        return err(
            DocErrorKind::BadName,
            1,
            format!("`{ident}` is not a package name ([a-z][a-z0-9-]{{0,31}})"),
        );
    }
    Ok(ident.replace('-', "_"))
}

/// What goes into a document.
pub struct AssembleInput<'a> {
    /// The implementation package (`vos-ready-bitmap`).
    pub impl_package: &'a str,
    /// The contract package (`vos-ready-contract`).
    pub contract_package: &'a str,
    /// `contract.part`.
    pub contract: &'a Part,
    /// `impl.part`.
    pub implementation: &'a Part,
    /// The obligations blocks, sorted and unique by tier.
    pub obligations: &'a [(Tier, &'a Part)],
}

/// Assemble the document text (VOS02 R2).  Total and deterministic: the same input
/// gives the same bytes.
pub fn assemble(input: &AssembleInput<'_>) -> Result<String, DocError> {
    let impl_name = document_name(input.impl_package)?;
    let contract_name = document_name(input.contract_package)?;
    for pair in input.obligations.windows(2) {
        if pair[0].0 >= pair[1].0 {
            return err(
                DocErrorKind::TierOrder,
                1,
                "obligations blocks are in tier order, each tier once",
            );
        }
    }
    let mut doc = String::new();
    doc.push_str(&format!("warrant {impl_name} v1\n"));
    doc.push_str(&format!(
        "  -- vos02:generated by vos-link gen-doc; do not edit; contract-package={contract_name}\n"
    ));
    doc.push_str(&format!(
        "  -- vos02:contract-begin sha256={}\n",
        input.contract.digest()
    ));
    doc.push_str(input.contract.text());
    doc.push_str("  -- vos02:contract-end\n");
    doc.push_str("  -- vos02:impl-begin\n");
    doc.push_str(input.implementation.text());
    doc.push_str("  -- vos02:impl-end\n");
    for (tier, part) in input.obligations {
        doc.push_str(&format!(
            "  -- vos02:obligations-begin tier={} sha256={}\n",
            tier.name(),
            part.digest()
        ));
        doc.push_str(part.text());
        doc.push_str("  -- vos02:obligations-end\n");
    }
    doc.push_str(TRAILER);
    if doc.len() > DOCUMENT_MAX_BYTES {
        return err(
            DocErrorKind::TooLarge,
            1,
            format!("the assembled document is over the {DOCUMENT_MAX_BYTES}-byte cap"),
        );
    }
    Ok(doc)
}

/// One block between markers.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Block {
    /// 1-based line of the begin marker.
    pub begin_line: usize,
    /// The bytes between the begin and end marker lines, exclusive.
    pub body: String,
    /// The digest the begin marker records (`None` for the implementation block,
    /// whose marker carries none).
    pub marker_sha256: Option<String>,
}

impl Block {
    /// SHA-256 of the body: what the marker's digest must equal.
    pub fn computed_sha256(&self) -> String {
        sha256_hex(self.body.as_bytes())
    }
}

/// The marker skeleton of a document, as read.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Layout {
    /// The first line (`warrant <name> v1` when generated).
    pub header: String,
    /// The `contract-package=` attribute of the generated marker.
    pub contract_package: String,
    /// The contract block.
    pub contract: Block,
    /// The implementation block.
    pub implementation: Block,
    /// The obligations blocks, in document order (sorted by tier, checked).
    pub obligations: Vec<(Tier, Block)>,
    /// Everything after the last end marker.
    pub trailer: String,
    /// The byte offset in the document at which the trailer starts.
    pub trailer_offset: usize,
}

/// Append the source text of a token.  The engine reports a newline token's value as
/// the two characters `\n` (an escaped spelling), not as the byte, so a newline is
/// written back as the byte it stands for; every other token carries its own text.
fn push_text(out: &mut String, t: &lexer::token::Token) {
    if token_kind(t) == "NEWLINE" {
        out.push('\n');
    } else {
        out.push_str(&t.value);
    }
}

/// The text of every token between the first and the last of a block's children.
fn block_of(node: &GrammarASTNode) -> (Vec<&lexer::token::Token>, String) {
    let mut toks = Vec::new();
    for c in &node.children {
        if let ASTNodeOrToken::Token(t) = c {
            toks.push(t);
        }
    }
    // First token: begin marker, then NEWLINE; last two: end marker, NEWLINE.
    let mut body = String::new();
    if toks.len() >= 4 {
        for t in &toks[2..toks.len() - 2] {
            push_text(&mut body, t);
        }
    }
    (toks, body)
}

/// The value of `key=` in a marker line, up to the next space.
fn attr<'a>(marker: &'a str, key: &str) -> Option<&'a str> {
    marker.split(' ').find_map(|word| word.strip_prefix(key))
}

/// Read the marker skeleton of a generated document.
pub fn parse_layout(bytes: &[u8]) -> Result<Layout, DocError> {
    let text = match admit_bytes(bytes, DOCUMENT_MAX_BYTES, DOCUMENT_MAX_LINE) {
        Ok(t) => t,
        Err(e) => {
            let kind = match e.kind {
                PartErrorKind::TooLarge => DocErrorKind::TooLarge,
                PartErrorKind::LineTooLong => DocErrorKind::LineTooLong,
                _ => DocErrorKind::Bytes,
            };
            return err(kind, e.line as usize, e.message);
        }
    };
    let tokens = match GrammarLexer::new(text, document_tokens()).tokenize() {
        Ok(t) => t,
        Err(e) => return err(DocErrorKind::Structure, e.line, e.message),
    };
    let root = match GrammarParser::new(tokens, document_grammar().clone()).parse() {
        Ok(r) => r,
        Err(e) => return err(DocErrorKind::Structure, e.token.line, e.message),
    };

    let mut header = String::new();
    let mut contract_package = String::new();
    let mut contract = None;
    let mut implementation = None;
    let mut obligations: Vec<(Tier, Block)> = Vec::new();
    let mut trailer = String::new();
    let mut seen_header = false;
    for child in &root.children {
        match child {
            ASTNodeOrToken::Token(t) => match token_kind(t).as_str() {
                "LINE" if !seen_header => {
                    header = t.value.clone();
                    seen_header = true;
                }
                "GENERATED" => {
                    contract_package = attr(&t.value, "contract-package=")
                        .unwrap_or_default()
                        .to_string();
                }
                // Header newline, generated newline, trailer lines.
                _ => {
                    if contract.is_some() {
                        push_text(&mut trailer, t);
                    }
                }
            },
            ASTNodeOrToken::Node(n) => {
                let (toks, body) = block_of(n);
                let begin = &toks[0];
                let block = Block {
                    begin_line: begin.line,
                    body,
                    marker_sha256: attr(&begin.value, "sha256=").map(str::to_string),
                };
                match n.rule_name.as_str() {
                    "contract_block" => contract = Some(block),
                    "impl_block" => implementation = Some(block),
                    _ => {
                        let tier = attr(&begin.value, "tier=").and_then(Tier::parse);
                        let Some(tier) = tier else {
                            return err(
                                DocErrorKind::Structure,
                                begin.line,
                                "an obligations marker with an unknown tier",
                            );
                        };
                        obligations.push((tier, block));
                    }
                }
            }
        }
    }
    let (Some(contract), Some(implementation)) = (contract, implementation) else {
        return err(
            DocErrorKind::Structure,
            1,
            "a contract or impl block is missing",
        );
    };
    for pair in obligations.windows(2) {
        if pair[0].0 >= pair[1].0 {
            return err(
                DocErrorKind::TierOrder,
                pair[1].1.begin_line,
                "obligations blocks are in tier order (any, canonical, policy, safety), each tier once",
            );
        }
    }
    let trailer_offset = text.len() - trailer.len();
    Ok(Layout {
        header,
        contract_package,
        contract,
        implementation,
        obligations,
        trailer,
        trailer_offset,
    })
}
